import fs from "node:fs";
import path from "node:path";
const PLUGIN_NAME = "vite-plugin-create-variables-forward";
function createVariables(content) {
    const names = [];
    for (const row of content.split("\n")) {
        if (!row.startsWith("$")) {
            continue;
        }
        const [key] = row.split(":");
        const name = key.trim();
        if (!name) {
            continue;
        }
        names.push(name);
    }
    return names;
}
function createUsePath(from, to) {
    const dirname = path.relative(path.dirname(to), from);
    const extname = path.extname(dirname);
    return dirname
        .slice(0, dirname.length - extname.length)
        .replaceAll("\\", "/")
        .replace(/(^|\/)_([^/]+)$/u, "$1$2");
}
function createContent(options, variableNames) {
    const file = createUsePath(options.from, options.to);
    const forwarded = variableNames
        .map((name) => `  ${name}: var.${name}`)
        .join(",\n");
    const lines = [
        "// DO NOT EDIT THIS FILE MANUALLY.",
        `// This file is auto-generated by ${PLUGIN_NAME} from ${options.from}.`,
        `@use '${file}' as var;`,
        `@forward '${options.module}' with (`,
        forwarded,
        ");",
    ];
    if (options.modules) {
        lines.push(...options.modules.map((module) => `@forward '${module}';`));
    }
    return lines.join("\n");
}
function variablesForward(options) {
    return {
        name: PLUGIN_NAME,
        buildStart() {
            const variables = createVariables(fs.readFileSync(options.from, { encoding: "utf-8" }));
            if (variables.length === 0) {
                return;
            }
            const content = createContent(options, variables);
            fs.writeFile(options.to, `${content}\n`, (err) => {
                if (err)
                    throw err;
                console.info(`Created ${options.to}`);
            });
        },
    };
}
export default variablesForward;
